const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dorsoidongCo = ee.Geometry.Point([82.5, 32.0]); // Approximate location of Dorsoidong Co
  const chibzhangCo = ee.Geometry.Point([82.8, 32.2]); // Approximate location of Chibzhang Co

  const date = '1987-10-12';
  const bufferDays = 5; // Buffer for date search

  // 2. Data Acquisition - Landsat 5 for 1987
  const landsatCol = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterDate('1987-10-07', '1987-10-17') // ±5 days buffer
    .filterBounds(ee.Geometry.MultiPoint([dorsoidongCo, chibzhangCo]));

  const colSize = landsatCol.size().getInfo();
  console.log(`Landsat 5 images in date range: ${colSize}`);

  if (colSize === 0) {
    console.log("No Landsat 5 images found for date range.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get closest image to target date
  const targetDate = ee.Date(date);
  const sortedCol = landsatCol.sort('system:time_start', false);
  const image = ee.Image(sortedCol.first());

  // 3. Processing - Extract blue band (SR_B1 for Landsat 5)
  const blueBand = 'SR_B1';

  // Define regions around lakes (5km buffers)
  const dorsoidongRegion = dorsoidongCo.buffer(5000); // 5km buffer
  const chibzhangRegion = chibzhangCo.buffer(5000); // 5km buffer

  // Calculate mean blue reflectance for each lake
  const dorsoidongStats = image.select(blueBand).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dorsoidongRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const chibzhangStats = image.select(blueBand).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: chibzhangRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const dorsoidongBlue = dorsoidongStats.get(blueBand).getInfo();
  const chibzhangBlue = chibzhangStats.get(blueBand).getInfo();

  // Check for valid pixels
  const dorsoidongCount = image.select(blueBand).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dorsoidongRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get(blueBand).getInfo();

  const chibzhangCount = image.select(blueBand).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: chibzhangRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get(blueBand).getInfo();

  console.log(`Dorsoidong Co - Blue: ${dorsoidongBlue?.toFixed(4)}, Pixels: ${dorsoidongCount}`);
  console.log(`Chibzhang Co - Blue: ${chibzhangBlue?.toFixed(4)}, Pixels: ${chibzhangCount}`);

  // 4. Validation & Final Answer
  if (dorsoidongCount === 0 || chibzhangCount === 0) {
    console.log("No valid pixels in one or both regions.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (dorsoidongBlue === null || chibzhangBlue === null || 
      isNaN(dorsoidongBlue) || isNaN(chibzhangBlue)) {
    console.log("Invalid reflectance values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare blue reflectance (higher value = lighter/lighter blue)
  const dorsoidongLighter = dorsoidongBlue > chibzhangBlue;

  console.log(`Comparison: Dorsoidong Co ${dorsoidongLighter ? 'lighter' : 'darker'} than Chibzhang Co`);

  if (dorsoidongLighter) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
